INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (14, 'other-form', N'joint return cap', N'25000', N'IRS, "Questions and answers about the new deduction for qualified overtime compensation" https://www.irs.gov/newsroom/questions-and-answers-about-the-new-deduction-for-qualified-overtime-compensation');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (14, @Known, 'known', N'https://www.irs.gov/newsroom/questions-and-answers-about-the-new-deduction-for-qualified-overtime-compensation', N'IRS, "Questions and answers about the new deduction for qualified overtime compensation"', N'The deduction is up to $12,500 of qualified overtime compensation earned for the year per return ($25,000 in the case of a joint return).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Same page also gives MAGI phase-out starts: $150,000 single / $300,000 joint.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (14, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:225%20edition:prelim)', N'refuter independent check', N'shall not exceed $12,500 ($25,000 in the case of a joint return). || up to $12,500 of qualified overtime compensation earned for the year per individual tax return ($25,000 in the case of a joint return)', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Value and kind confirmed. Source problem: the researcher cited the IRS Q&A web page, which is FS-2026-01 and now states it is superseded by FS-2026-13 (August 2026). Read FS-2026-13 in full text: Q2 (updated Aug 6, 2026) keeps $12,500/$25,000. Cite FS-2026-13 and 26 USC 225(b)(1) instead. Not indexed; no deduction for years beginning after Dec 31, 2028; married must file jointly.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (15, 'outdated', N'2025 wage base', N'176100', N'SSA, "Cost-of-Living Increase and Other Determinations for 2025," Federal Register notice 2024-24871 (Oct. 25, 2024) https://www.govinfo.gov/content/pkg/FR-2024-10-25/pdf/2024-24871.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (15, @Known, 'known', N'https://www.govinfo.gov/content/pkg/FR-2024-10-25/pdf/2024-24871.pdf', N'SSA, "Cost-of-Living Increase and Other Determinations for 2025," Federal Register notice 2024-24871 (Oct. 25, 2024)', N'The OASDI contribution and benefit base is $176,100 for remuneration paid in 2025 and self-employment income earned in tax years beginning in 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Also cross-checked against the 2026 notice (2025-19763), which independently states the prior base was $176,100.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (15, @Known, 'known', N'https://www.federalregister.gov/documents/full_text/text/2024/10/25/2024-24871.txt', N'refuter independent check', N'The OASDI contribution and benefit base is $176,100 for remuneration paid in 2025 || Because $184,500 exceeds the current base amount of $176,100, the OASDI contribution and benefit base is $184,500 for 2026.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Both SSA FR notices read in full as federalregister.gov raw text (not govinfo, which the researcher cited). The 2026 notice (FR 2025-19763, Nov 3 2025) also confirms the key 184500 and names 176100 as the prior base. No correction notice found. ssa.gov/oact/cola/cbb.html returned 403, so not used.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (15, 'outdated', N'2024 wage base', N'168600', N'https://www.federalregister.gov/documents/full_text/text/2024/10/25/2024-24871.txt');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (15, @Known, 'known', N'https://www.federalregister.gov/documents/full_text/text/2024/10/25/2024-24871.txt', N'refuter independent check', N'Because $176,100 exceeds the current base amount of $168,600, the OASDI contribution and benefit base is $176,100 for 2025.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind outdated. $168,600 is the base in effect when the 2025 notice was issued (2024). Read full text of FR 2024-24871.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (16, 'outdated', N'2025 limit', N'23500', N'IRS Newsroom, "401(k) limit increases to $24,500 for 2026, IRA limit increases to $7,500" https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, @Known, 'known', N'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500', N'IRS Newsroom, "401(k) limit increases to $24,500 for 2026, IRA limit increases to $7,500"', N'the amount individuals can contribute to their 401(k) plans in 2026 has increased to $24,500, up from $23,500 for 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Raw HTML fetched and tag-stripped, not WebFetch''s AI summary.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-25-67.pdf', N'refuter independent check', N'which includes elective deferrals made to the Thrift Savings Plan, is increased from $23,500 to $24,500. || increased to $24,500, up from $23,500 for 2025', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Notice 2025-67 PDF text extracted with PdfPig; IR-2025-111 HTML fetched and tag-stripped. Section 402(g)(1) figure, excludes catch-up. Key 24500 confirmed.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (16, 'outdated', N'2024 limit', N'23000', N'https://www.irs.gov/pub/irs-drop/n-24-80.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-24-80.pdf', N'refuter independent check', N'which includes elective deferrals made to the Thrift Savings Plan, is increased from $23,000 to $23,500.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind outdated. Notice 2024-80 (2025 COLAs) PDF text extracted; states the 2024 402(g)(1) limit as $23,000.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (16, 'other-form', N'2026 total including age-50 catch-up', N'32500', N'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, @Known, 'known', N'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500', N'refuter independent check', N'who are 50 and older generally can contribute up to $32,500 each year, starting in 2026', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind other-form. Deferral plus $8,000 catch-up; the question excludes catch-up. Same page: ages 60-63 catch-up remains $11,250 (total $35,750, not added as its own entry).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (17, 'outdated', N'2025 limit', N'4300', N'IRS Rev. Proc. 2024-25 (2025 HSA inflation-adjusted amounts) https://www.irs.gov/pub/irs-drop/rp-24-25.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-25.pdf', N'IRS Rev. Proc. 2024-25 (2025 HSA inflation-adjusted amounts)', N'For calendar year 2025, the annual limitation on deductions under § 223(b)(2)(A) for an individual with self-only coverage under a high deductible health plan is $4,300.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'PDF text extracted via PdfPig, not just a search snippet.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-25.pdf', N'refuter independent check', N'For calendar year 2025, the annual limitation on deductions under § 223(b)(2)(A) for an individual with self-only coverage under a high deductible health plan is $4,300.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Rev. Proc. 2024-25 PDF text extracted with PdfPig, whole document read (2 pages). 2025 family was $8,550 in the same doc. OBBBA did not change 223(b)(2); uscode 223 still shows the $2,250/$4,500 statutory bases.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (17, 'outdated', N'2024 limit', N'4150', N'https://www.irs.gov/pub/irs-drop/rp-23-23.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-23-23.pdf', N'refuter independent check', N'For calendar year 2024, the annual limitation on deductions under § 223(b)(2)(A) for an individual with self-only coverage under a high deductible health plan is $4,150.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind outdated. Rev. Proc. 2023-23 PDF text extracted. (Its section heading misprints ''2023 INFLATION ADJUSTED ITEMS'' but the operative text says calendar year 2024.)', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (17, 'other-form', N'2026 family coverage limit', N'8750', N'IRS Rev. Proc. 2025-19 (2026 HSA inflation-adjusted amounts) https://www.irs.gov/pub/irs-drop/rp-25-19.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-25-19.pdf', N'IRS Rev. Proc. 2025-19 (2026 HSA inflation-adjusted amounts)', N'For calendar year 2026, the annual limitation on deductions under § 223(b)(2)(B) for an individual with family coverage under a high deductible health plan is $8,750.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Same Rev. Proc. also confirms self-only 2026 = $4,400, matching the key.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-25-19.pdf', N'refuter independent check', N'For calendar year 2026, the annual limitation on deductions under § 223(b)(2)(B) for an individual with family coverage under a high deductible health plan is $8,750.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Rev. Proc. 2025-19 fully read; same doc gives self-only $4,400 (key confirmed). Correct tier and year.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (17, 'other-form', N'2026 self-only including age-55 catch-up', N'5400', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:223%20edition:prelim) | https://www.irs.gov/pub/irs-drop/rp-25-19.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:223%20edition:prelim)', N'refuter independent check', N'2009 and thereafter $1,000. || for an individual with self-only coverage under a high deductible health plan is $4,400', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind other-form. Derived, not a single published figure: $4,400 (Rev. Proc. 2025-19) plus the unindexed $1,000 additional contribution for age 55+ under 26 USC 223(b)(3)(B). Label as inferred-by-addition if published.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (18, 'outdated', N'limit before 2026', N'5000', N'26 U.S.C. §129(a)(2)(A), Editorial Notes — Amendments (2025) https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)', N'26 U.S.C. §129(a)(2)(A), Editorial Notes — Amendments (2025)', N'Pub. L. 119–21 substituted "$7,500 ($3,750" for "$5,000 ($2,500". ... shall apply to taxable years beginning after December 31, 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'OBBBA (Pub. L. 119-21 §70404) raised the unindexed $5,000 figure to $7,500 starting tax year 2026, confirming both the key and this outdated value in one statutory note.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)', N'refuter independent check', N'Pub. L. 119–21 substituted "$7,500 ($3,750" for "$5,000 ($2,500". || For 2025, the maximum amount that can be excluded from an employee''s income through a dependent care assistance program is $5,000 ($2,500 if married filing separately). || (D) Special rule for 2021 ... substituting "$10,500 (half such dollar amount" for "$5,000 ($2,500".', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Value and kind confirmed (was the 2025 limit; Pub 503 (2025) and Pub 15-B (2026) both say raised from $5,000 to $7,500 for 2026). LABEL IS WRONG and must be fixed before public use: the $5,000 cap was added by Pub. L. 99-514 §1163, effective for taxable years beginning after Dec 31, 1986 (so 1987, not 1986), and 2021 was $10,500 under §129(a)(2)(D) (ARPA). Suggested label: ''2025 limit (in effect 1987-2025 except 2021)''.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (18, 'outdated', N'2021 temporary limit (American Rescue Plan Act)', N'10500', N'https://www.irs.gov/pub/irs-prior/p503--2021.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://www.irs.gov/pub/irs-prior/p503--2021.pdf', N'refuter independent check', N'For 2021, the maximum amount is increased to $10,500 (previously $5,000).', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind outdated. Official limit for this same thing (non-MFS) for tax year 2021 only; also in 26 USC 129(a)(2)(D). Pub 503 (2021) PDF text extracted.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (18, 'other-form', N'2026 limit, married filing separately', N'3750', N'26 U.S.C. §129(a)(2)(A) (current text, as amended by Pub. L. 119-21) https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)', N'26 U.S.C. §129(a)(2)(A) (current text, as amended by Pub. L. 119-21)', N'shall not exceed $7,500 ($3,750 in the case of a separate return by a married individual).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Worth flagging: $3,750 is the 2026 MFS half-limit, easily confused with the $7,500 MFJ/single figure. (The pre-2026 MFS half-limit was $2,500, also in this same statutory note.)', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:129%20edition:prelim)', N'refuter independent check', N'shall not exceed $7,500 ($3,750 in the case of a separate return by a married individual). || Dependent care assistance Exempt3 up to certain limits, $7,500 ($3,750 for married employee filing separate return).', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Researcher''s NEW entry confirmed, kind other-form. Pub 15-B is the 2026 edition (''For use in 2026''). Effective date note: Pub. L. 119-21 §70404(b), taxable years beginning after Dec 31, 2025.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (18, 'other-form', N'child and dependent care credit expense cap, 2+ qualifying persons', N'6000', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:21%20edition:prelim)');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=(title:26%20section:21%20edition:prelim)', N'refuter independent check', N'(2) $6,000 if there are 2 or more qualifying individuals with respect to the taxpayer for such taxable year.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind other-form. Section 21(c) credit expense limit, a different benefit often conflated with the 129 FSA exclusion; not an older value of the FSA limit. uscode prelim text already reflects Pub. L. 119-21 (seen in 129 notes). 1-person cap is $3,000.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (19, 'outdated', N'2025 amount after the One Big Beautiful Bill Act', N'15750', N'Rev. Proc. 2025-32, Section 3.01 https://www.irs.gov/pub/irs-drop/rp-25-32.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'Rev. Proc. 2025-32, Section 3.01', N'for any taxable year beginning in 2025... Unmarried Individuals (other than Surviving Spouses and Heads of Households) (§ 1(j)(2)(C)) $15,750', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly. Rev. Proc. 2025-32 (issued to reflect OBBBA, Public Law 119-21) modifies Rev. Proc. 2024-40''s 2025 standard deduction; OBBBA §70102 raised the 2025 single/MFS base amount to $15,750.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'refuter independent check', N'Section 3.01: standard deduction amounts under § 63(c)(2) for any taxable year beginning in 2025 ... Unmarried Individuals ... (§ 1(j)(2)(C)) $15,750. Accordingly, section 2.15(1) of Rev. Proc. 2024-40 is removed. || 26 USC 63(c)(7)(A)(ii): by substituting "$15,750" for "$3,000" in subparagraph (C); amendment note: Pub. L. 119-21, §70102(b)(2), substituted "$15,750" for "$12,000".', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. Evidence field holds SUPPORTING quotes (nothing refuted). Two independent primaries read this session via full PDF text + uscode HTML: IRS Rev. Proc. 2025-32 §3.01 and the statute itself. Same 2026 Rev. Proc. §4.14(1) shows key $16,100, so 15,750 is a prior official value of the same item. read_how: full-page-or-pdf-text.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (19, 'outdated', N'2025 amount as first announced', N'15000', N'Rev. Proc. 2024-40, Section 3.15(1) https://www.irs.gov/pub/irs-drop/rp-24-40.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-40.pdf', N'Rev. Proc. 2024-40, Section 3.15(1)', N'For taxable years beginning in 2025, the standard deduction amounts... Unmarried Individuals (other than Surviving Spouses and Heads of Households) (§ 1(j)(2)(C)) $15,000', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly. This is the pre-OBBBA 2025 figure, later superseded to $15,750 by Rev. Proc. 2025-32 (see 6a row above).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-40.pdf', N'refuter independent check', N'Section 2.15(1): For taxable years beginning in 2025, the standard deduction amounts under § 63(c)(2) ... Unmarried Individuals ... (§ 1(j)(2)(C)) $15,000 || section 2.15(1) of Rev. Proc. 2024-40 is removed.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Value survives. Citation error in researcher output: it is Rev. Proc. 2024-40 SECTION 2.15(1), not 3.15(1) (Rev. Proc. 2024-40 Section 2 is ''2025 ADJUSTED ITEMS''; Section 3 is Effective Date). Confirmed superseded by Rev. Proc. 2025-32 §3.01, so ''outdated'' is right. read_how: full-page-or-pdf-text.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (19, 'outdated', N'2024 amount', N'14600', N'https://www.irs.gov/pub/irs-drop/rp-23-34.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-23-34.pdf', N'refuter independent check', N'Section 3.15(1): For taxable years beginning in 2024 ... Unmarried Individuals (other than Surviving Spouses and Heads of Households) (§ 1(j)(2)(C)) $14,600', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=outdated. Primary PDF read this session.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (19, 'other-form', N'2026 married filing jointly amount', N'32200', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'refuter independent check', N'Section 4.14(1): For taxable years beginning in 2026 ... Married Individuals Filing Joint Returns and Surviving Spouses (§ 1(j)(2)(A)) $32,200; Heads of Households $24,150', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=other-form (wrong filing status, right year). HOH $24,150 is the same kind if wanted. MFS $16,100 equals the key, so it is not a distractor.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (20, 'outdated', N'2013-2017 top rate', N'39.6', N'Rev. Proc. 2016-55, Section 3.01 (2017 tax rate tables) https://www.irs.gov/pub/irs-drop/rp-16-55.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (20, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-16-55.pdf', N'Rev. Proc. 2016-55, Section 3.01 (2017 tax rate tables)', N'Over $418,400 $121,505.25 plus 39.6% of the excess over $418,400 [Table 3 - Unmarried Individuals]', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed for 2017 (last year of the range) directly from the IRS''s own 2017 rate tables in Rev. Proc. 2016-55; the 39.6% top bracket (established by ATRA 2012) ran 2013-2017 and ended with TCJA''s 37% top rate starting 2018.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (20, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-13-15.pdf', N'refuter independent check', N'Section 2.01, 2013 Table 3 Unmarried Individuals: Over $400,000 $116,163.75 plus 39.6% of the excess over $400,000 || Section 3.01, 2017 Table 3 Unmarried Individuals: Over $418,400 $121,505.25 plus 39.6% of the excess over $418,400 || Section 2.01: OBBBA amends § 1(j) to make the tax rate tables ... permanent. The existing seven tax rates of 10%, 12%, 22%, 24%, 32%, 35%, and 37% remain in effect', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. Both endpoints of the 2013-2017 range confirmed from IRS rate tables (2013 via Rev. Proc. 2013-15, which the researcher did not check; 2017 via Rev. Proc. 2016-55). 2014-2016 inferred from unchanged statute (26 USC 1(a)-(e) tables still carry 39.6%; 1(j)(1) overrides only for years after 2017), not read year by year. 39.6 was also the 1993-2000 top rate, so the label is not exhaustive but not wrong.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (21, 'other-form', N'federal tipped cash wage', N'2.13', N'Federal Register 2024-29798, Tip Regulations Under the FLSA (DOL, Dec 17 2026 reinstatement of regulatory text) https://www.federalregister.gov/documents/2024/12/17/2024-29798/tip-regulations-under-the-fair-labor-standards-act-flsa-restoration-of-regulatory-language');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, @Known, 'known', N'https://www.federalregister.gov/documents/2024/12/17/2024-29798/tip-regulations-under-the-fair-labor-standards-act-flsa-restoration-of-regulatory-language', N'Federal Register 2024-29798, Tip Regulations Under the FLSA (DOL, Dec 17 2026 reinstatement of regulatory text)', N'employer must pay the tipped employee a direct cash wage of at least $2.13 per hour.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed via Federal Register (DOL Wage & Hour Division). Statute text itself (29 U.S.C. 203(m), fetched at uscode.house.gov) doesn''t restate the dollar figure literally, only cross-refs ''the wage in effect on Aug 20, 1996''; the FR document gives the operative $2.13 figure directly. Unchanged since 1991.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, @Known, 'known', N'https://www.federalregister.gov/documents/full_text/text/2024/12/17/2024-29798.txt', N'refuter independent check', N'the employer must pay the tipped employee a direct cash wage of at least $2.13 per hour || not less than the cash wage required to be paid such an employee on August 20, 1996', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed, read_how full text. The FR HTML page is CAPTCHA-walled for scripts, so I read it through the FR API raw text (FR Doc 2024-29798). That document was published Dec 17 2024, not 2026 as the researcher''s description says. 29 USC 206 at uscode.house.gov is ''in effect on September 16, 2026'' and still says $7.25 (key holds). 2.13 is a different figure from the same law, so other-form is correct.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (21, 'other-form', N'maximum FLSA tip credit', N'5.12', N'https://www.federalregister.gov/documents/full_text/text/2024/12/17/2024-29798.txt');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, @Known, 'known', N'https://www.federalregister.gov/documents/full_text/text/2024/12/17/2024-29798.txt', N'refuter independent check', N'the employer may claim a tip credit against its wage obligation of up to $5.12 per hour', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Other-form. Researcher''s extra entry holds.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (21, 'other-form', N'FLSA youth opportunity wage', N'4.25', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title29-section206&num=0&edition=prelim');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title29-section206&num=0&edition=prelim', N'refuter independent check', N'during the first 90 consecutive calendar days ... a wage which is not less than $4.25 an hour', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed in current 29 USC 206(g). Other-form. Note that $4.25 was also the general federal minimum before Oct 1 1996, so a 4.25 answer is ambiguous. Grade it other-form, not outdated.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (22, 'outdated', N'2025 rate', N'16.66', N'WA L&I Minimum Wage page https://lni.wa.gov/workers-rights/wages/minimum-wage/');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, @Known, 'known', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/', N'WA L&I Minimum Wage page', N'The 2025 minimum wage in the state of Washington was $16.66 per hour. ... The 2026 minimum wage in the state of Washington is $17.13 per hour.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed at lni.wa.gov: 2025=$16.66, 2026=$17.13 (matches key).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, @Known, 'known', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/', N'refuter independent check', N'The 2025 minimum wage in the state of Washington was $16.66 per hour. || Washington''s current state minimum wage of $16.66 is the highest in the nation.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed from two L&I pages: the rate page and the Sept 30 2025 release (#25-27). 2026 = $17.13, so the key holds. The 2027 rate is not announced yet (L&I announces Sept 30), so the key is not stale as of 2026-09-17. Outdated fits the benchmark''s last-year convention.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (22, 'other-form', N'2026 rate for ages 14-15 (85%)', N'14.56', N'https://www.lni.wa.gov/news-events/article/25-27');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, @Known, 'known', N'https://www.lni.wa.gov/news-events/article/25-27', N'refuter independent check', N'the minimum wage for those younger workers will be $14.56 an hour in 2026', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Other-form. The question''s ''16+'' wording is there to exclude this figure.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (22, 'other-form', N'Seattle 2026 local minimum wage', N'21.30', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/local-minimum-wage-rates');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, @Known, 'known', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/local-minimum-wage-rates', N'refuter independent check', N'Seattle: $21.30/hour.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed on L&I''s local-rates page. Other-form: local, not statewide. The same page lists other cities (SeaTac $20.74 hospitality/transport, Tukwila $21.65, etc.).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (23, 'other-form', N'local unit property tax administration fee cap (MCL 211.44)', N'1', N'MCL 211.44 (Michigan Compiled Laws, current through PA 91 of 2026) https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, @Known, 'known', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44', N'MCL 211.44 (Michigan Compiled Laws, current through PA 91 of 2026)', N'the local property tax collecting unit shall add a property tax administration fee of not more than 1% of the total tax bill per parcel ... A 4% county property tax administration fee ... shall be added to taxes collected by the township or city treasurer after [return as delinquent]', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Same MCL 211.44 contains both figures: local collecting-unit fee capped at 1%, county fee on delinquent-return is 4% (the key). Both confirmed in one read.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, @Known, 'known', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44', N'refuter independent check', N'shall add a property tax administration fee of not more than 1% of the total tax bill per parcel || A county property tax administration fee of 4% and ... interest computed at a noncompounded rate of 1% per month', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. MCL 211.78a(3) is the cleaner source for the key: 4% added to property returned delinquent, with a $1.00 minimum. MCL 211.44(3) also says 4%, for taxes the local treasurer collects late. A ''1'' answer could also come from the 1%/month interest in 211.78a(3), but either way it is other-form, not outdated.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (23, 'other-form', N'local late penalty after February 14 (MCL 211.44(3))', N'3', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, @Known, 'known', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44', N'refuter independent check', N'a late penalty charge equal to 3% of the tax', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Other-form. A local-unit penalty for taxes paid after Feb 14 and before return to the county; not the county admin fee.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (24, 'other-form', N'October 1 fee (MCL 211.78d)', N'15', N'MCL 211.78d (Michigan Compiled Laws) https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-78d');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (24, @Known, 'known', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-78d', N'MCL 211.78d (Michigan Compiled Laws)', N'the county treasurer shall add a $15.00 fee on each parcel of property for which the delinquent taxes, interest, penalties, and fees remain unpaid.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'MCL 211.78d $15 fee is distinct from the $175 MCL 211.78g forfeiture fee (the key).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (24, @Known, 'known', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-78d', N'refuter independent check', N'211.78d Additional fee; October 1. ... the county treasurer shall add a $15.00 fee on each parcel', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Other-form. 78d was last amended by 2003 PA 263 and has said $15.00 since 1999 PA 123.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (25, 'other-form', N'C# 13, the .NET 9 default', N'13', N'Set the C# language version (learn.microsoft.com) https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version | C# language versioning history (learn.microsoft.com) https://learn.microsoft.com/en-us/dotnet/csharp/whats-new/csharp-version-history');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, @Known, 'known', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version', N'Set the C# language version (learn.microsoft.com)', N'changing the target TFM (for example, from .NET 6 to .NET 9) updates the language version accordingly, from C# 10 to C# 13.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Doc explicitly pairs .NET 9 with C# 13 default (matches proposed outdated value). C# 14 (Nov 2025) ships with .NET 10 (key=14), same pattern.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, @Known, 'known', N'https://learn.microsoft.com/en-us/dotnet/csharp/whats-new/csharp-version-history', N'C# language versioning history (learn.microsoft.com)', N'C# version 14 Released November 2025', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Doc explicitly pairs .NET 9 with C# 13 default (matches proposed outdated value). C# 14 (Nov 2025) ships with .NET 10 (key=14), same pattern.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, @Known, 'known', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/language-versioning', N'refuter independent check', N'.NET 11.x C# 15 .NET 10.x C# 14 .NET 9.x C# 13 || If your project targets a preview framework that has a corresponding preview language version, the language version used is the preview language version.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Value confirmed (.NET 9.x defaults to C# 13; key C# 14 for .NET 10.x confirmed in the same table). The kind label is wrong. The question pins .NET 10, and C# 13 was never the default for a net10.0 target: preview TFMs got the preview language version. So 13 answers a different question (the .NET 9 default), which is other-form under the schema. This is unlike 7b, where 16.66 really was the WA statewide rate. Relabel as other-form, or reword the question to ''current .NET'' if you want an outdated value.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (25, 'other-form', N'C# 15, the .NET 11 default', N'15', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/language-versioning');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, @Known, 'known', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/language-versioning', N'refuter independent check', N'.NET 11.x C# 15', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Other-form, one release ahead. .NET 11 is still pre-release (RC1 Sept 8 2026 per dotnet.microsoft.com). A model that answers 15 is confusing it with the upcoming release, not reciting an old value.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (26, 'other-form', N'.NET 8 and .NET 9 end of support date', N'2026-11-10', N'.NET and .NET Core Support Policy (dotnet.microsoft.com) https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (26, @Known, 'known', N'https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core', N'.NET and .NET Core Support Policy (dotnet.microsoft.com)', N'.NET 10 November 11, 2025 10.0.12 September 8, 2026 LTS Active November 14, 2028 / .NET 9 November 12, 2024 9.0.20 September 8, 2026 STS Maintenance November 10, 2026 / .NET 8 November 14, 2023 8.0.31 September 8, 2026 LTS Maintenance November 10, 2026', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'.NET 10 EOL 2028-11-14 (key) confirmed same table. .NET 8 EOL 2026-11-10 confirmed. Note .NET 9 (STS) also shows 2026-11-10 as EOL on this same page -- don''t conflate the two if asked separately.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (26, @Known, 'known', N'https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core', N'refuter independent check', N'.NET 8 November 14, 2023 8.0.31 September 8, 2026 LTS Maintenance November 10, 2026', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed. Key .NET 10 = November 14, 2028 is in the same table. .NET 9 (STS) also ends November 10, 2026, so a 2026-11-10 answer could come from either version. Both are other-form. I found no primary source showing a different earlier published .NET 10 end-of-support date, so there is no outdated value.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (27, 'outdated', N'2025 percentage', N'9.02', N'Rev. Proc. 2024-35, Section 2.02(2) https://www.irs.gov/pub/irs-drop/rp-24-35.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-35.pdf', N'Rev. Proc. 2024-35, Section 2.02(2)', N'For plan years beginning in calendar year 2025, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 9.02%.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-35.pdf', N'refuter independent check', N'Section 2.02(2): For plan years beginning in calendar year 2025, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 9.02%. || Section 3.02: For plan years beginning in calendar year 2026, the Required Contribution Percentage ... is 9.96%.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. Key 9.96 also re-read in Rev. Proc. 2025-25. Rev. Proc. 2026-26 covers 2027 only and does not revise 2026. read_how: full-page-or-pdf-text.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (27, 'outdated', N'2024 percentage', N'8.39', N'https://www.irs.gov/pub/irs-drop/rp-23-29.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-23-29.pdf', N'refuter independent check', N'(2) For plan years beginning in calendar year 2024, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 8.39%.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=outdated.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (27, 'outdated', N'original statutory percentage (2014)', N'9.5', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title26-section36B&num=0&edition=prelim');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title26-section36B&num=0&edition=prelim', N'refuter independent check', N'36B(c)(2)(C)(i)(II): ... exceeds 9.5 percent of the applicable taxpayer''s household income. (iv) Indexing: In the case of plan years beginning in any calendar year after 2014, the Secretary shall adjust the 9.5 percent', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=outdated (the statutory 9.5% was the operative value for 2014 plan years; indexing starts after 2014). Very common model answer.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (27, 'other-form', N'2027 percentage', N'10.22', N'Rev. Proc. 2026-26, Section 3.02 https://www.irs.gov/pub/irs-drop/rp-26-26.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-26-26.pdf', N'Rev. Proc. 2026-26, Section 3.02', N'For plan years beginning in calendar year 2027, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 10.22%.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly. Rev. Proc. 2026-26 (released July 21, 2026) sets the 2027 figure at 10.22%, up from 9.96% for 2026 (Rev. Proc. 2025-25, key value for this question).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-26-26.pdf', N'refuter independent check', N'Section 3.02: For plan years beginning in calendar year 2027, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 10.22%.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. ''other-form'' is the right kind: a future-year value, never the answer for 2026 plan years. Rev. Proc. 2026-26 release date (researcher said July 21, 2026) not verified; irrelevant to the value.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (27, 'other-form', N'premium tax credit contribution cap (different ACA percentage)', N'8.5', N'https://www.irs.gov/pub/irs-drop/rp-24-35.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/rp-24-35.pdf', N'refuter independent check', N'Section 2.01 Applicable Percentage Table for 2025: At least 400% and higher 8.50% 8.50%', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=other-form. This is the §36B(b)(3)(A) PTC contribution cap, not the §36B(c)(2)(C) affordability percentage. The two get conflated.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (28, 'outdated', N'Jan 1 to Jun 30, 2026 rate', N'72.5', N'IRS Notice 2026-10, Section 3 https://www.irs.gov/pub/irs-drop/n-26-10.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-26-10.pdf', N'IRS Notice 2026-10, Section 3', N'The standard mileage rate for transportation or travel expenses for 2026 is 72.5 cents per mile for all miles of business use (business standard mileage rate).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly. This was the original 2026 rate per Notice 2026-10; it was superseded for miles driven on/after July 1, 2026 by a mid-year increase to 76 cents (per IRS newsroom item ''IRS sets 2026 business standard mileage rate at 72.5 cents...'' plus later Announcement 2026-11 amending Notice 2026-10, per secondary trade-press reporting -- the July 1 change itself was not re-verified since it is the given key).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-26-10.pdf', N'refuter independent check', N'Section 3: The standard mileage rate for transportation or travel expenses for 2026 is 72.5 cents per mile for all miles of business use || Announcement 2026-11 ... The revised standard mileage rates are: (1) Business 76 cents per mile (2) Medical and moving 23.5 cents per mile ... apply to ... expenses paid or incurred ... on or after July 1, 2026 ... Notice 2026-10 is modified. || 2026 (July 1 – Dec. 31) 76 14 23.5 ... 2026 (Jan. 1 – June 30) 72.5 14 20.5', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. Researcher called the July 1 change ''secondary trade-press''; it is now PRIMARY-confirmed: Announcement 2026-11 in IRB 2026-29 (July 13, 2026) modifies Notice 2026-10, plus the IRS mileage-rate table (page last reviewed 28-Jul-2026). 72.5 applied to all 2026 miles until the announcement, so ''outdated'' is correct. read_how: full-page-or-pdf-text.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (28, 'outdated', N'2025 rate', N'70', N'IRS Notice 2025-5, Section 3 https://www.irs.gov/pub/irs-drop/n-25-05.pdf');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-25-05.pdf', N'IRS Notice 2025-5, Section 3', N'The standard mileage rate for transportation or travel expenses for 2025 is 70 cents per mile for all miles of business use (business standard mileage rate).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Confirmed exactly.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/pub/irs-drop/n-25-05.pdf', N'refuter independent check', N'Section 3: The standard mileage rate for transportation or travel expenses for 2025 is 70 cents per mile for all miles of business use || 2025 70 14 21 IR-2024-312', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Survived. The IRS table shows one 2025 row, so there was no mid-year 2025 change. read_how: full-page-or-pdf-text.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (28, 'outdated', N'2024 rate', N'67', N'https://www.irs.gov/tax-professionals/standard-mileage-rates');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/tax-professionals/standard-mileage-rates', N'refuter independent check', N'2024 67 14 21 IR-2023-239', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=outdated. Read from the IRS rate table HTML, not from the underlying notice.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (28, 'other-form', N'medical and moving rate from July 1, 2026', N'23.5', N'https://www.irs.gov/irb/2026-29_irb');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, @Known, 'known', N'https://www.irs.gov/irb/2026-29_irb', N'refuter independent check', N'Announcement 2026-11: The revised standard mileage rates are: (1) Business 76 cents per mile (2) Medical and moving 23.5 cents per mile', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'NEW, kind=other-form (right period, wrong purpose). Charitable 14 cents (fixed by § 170(i), same announcement) is the same kind.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.QuestionKnownAnswer (QuestionId, Kind, Label, Answer, Source) VALUES (29, 'other-form', N'float16 preview limit', N'3996', N'Half-precision float support in vector data type (learn.microsoft.com, SQL Server 2025) https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type-half-precision-float?view=sql-server-ver17 | vector (Transact-SQL) (learn.microsoft.com) https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type?view=sql-server-ver17');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (29, @Known, 'known', N'https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type-half-precision-float?view=sql-server-ver17', N'Half-precision float support in vector data type (learn.microsoft.com, SQL Server 2025)', N'SQL Server supports vectors with up to 3,996 dimensions (1998 x 2) when using float16. This feature doubles the limitation 1,998 dimensions for float32.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'1998 = default float32 max (key). 3996 = float16 preview max (proposed, confirmed exact match). float16 is still preview-gated (PREVIEW_FEATURES).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (29, @Known, 'known', N'https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type?view=sql-server-ver17', N'vector (Transact-SQL) (learn.microsoft.com)', N'The maximum number of dimensions supported is 1998.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'1998 = default float32 max (key). 3996 = float16 preview max (proposed, confirmed exact match). float16 is still preview-gated (PREVIEW_FEATURES).', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, KnownAnswerId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (29, @Known, 'known', N'https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type-half-precision-float?view=sql-server-ver17', N'refuter independent check', N'SQL Server supports vectors with up to 3,996 dimensions ( 1998 x 2 ) when using float16 || The maximum number of dimensions supported is 1998.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'Confirmed on both pages. Default base type is float32 (key 1998). float16 is still preview-gated behind PREVIEW_FEATURES. Other-form is correct.', 'wf_0c0a041d-4d2');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (15, 'key', N'https://www.federalregister.gov/documents/2025/11/03/2025-19763/cost-of-living-increase-and-other-determinations-for-2026', N'Cost-of-Living Increase and Other Determinations for 2026, 90 FR 49047, Notice, Doc. 2025-19763 (11/3/2025)', N'The OASDI contribution and benefit base is $184,500 for remuneration paid in 2026 and self-employment income earned in tax years beginning in 2026.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Yes — up from $176,100 (2025) to $184,500 (2026), per the SSA''s annual wage-index-based formula.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (15, 'key', N'https://www.federalregister.gov/documents/2025/11/03/2025-19763/cost-of-living-increase-and-other-determinations-for-2026', N'refuter independent check', N'Confirmed. (1) Downloaded the full Federal Register notice 2025-19763 (90 FR 49047). It says the OASDI contribution and benefit base is $184,500 for remuneration paid in 2026, computed as $184,548.71 rounded to $184,500, replacing $176,100. (2) Pulled the Federal Register API list of every SSA document from 2025-11-04 to 2026-09-16 (47 docs). There is no correction or revision to the 2026 determinations. (3) Downloaded IRS Pub 15 (2026) and read its text with PdfPig. It says ''The social security wage base limit is $184,500'' and repeats it in several places. SSA''s cbb.html and colafacts2026.pdf returned 403 and were not read.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key 184500 holds. Only one figure fits ''maximum earnings subject to Social Security tax'' for 2026 (Medicare has no cap, FUTA is $7,000, household-worker threshold $3,000 is a different concept). The researcher''s version (no $ sign, no commas) is fine and removes grading noise.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, 'key', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title29-section206&num=0&edition=prelim', N'29 U.S.C. § 206(a)(1)(C), Fair Labor Standards Act, current U.S. Code (prelim edition)', N'$7.25 an hour, beginning 24 months after that 60th day;', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Unchanged — federal minimum wage has been $7.25/hr since July 24, 2009 (no legislative change since).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, 'key', N'https://www.dol.gov/agencies/whd/minimum-wage', N'DOL WHD Minimum Wage webpage', N'The federal minimum wage is $7.25 per hour effective July 24, 2009.', 'webfetch-summary-only', 'research-agent', 'confirmed', N'Unchanged — federal minimum wage has been $7.25/hr since July 24, 2009 (no legislative change since).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (21, 'key', N'https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title29-section206&num=0&edition=prelim', N'refuter independent check', N'Confirmed. (1) Downloaded the Title 29 USLM XML at the latest release point, current through Public Law 119-108 (09/11/2026). 29 U.S.C. 206(a)(1)(C) still reads ''$7.25 an hour'', so no 2025-2026 law changed it. (2) The prelim section page (currentthrough 20260413_119-83) agrees. (3) dol.gov returned 403 to curl, so the DOL page was read by WebFetch summary only: ''The federal minimum wage is $7.25 per hour effective July 24, 2009.''', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Draft is fine. The researcher''s added ''standard rate, not the tipped minimum'' is harmless and closes off $2.13. The youth rate ($4.25) and the old contractor rate are also excluded by ''standard FLSA rate''. The EO 14026 contractor minimum was rescinded in 2025, so it doesn''t compete. Grader should accept 7.25 with or without a $ sign.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, 'key', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/', N'L&I Minimum Wage webpage', N'The 2026 minimum wage in the state of Washington is $17.13 per hour.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Yes — up from $16.66 (2025) to $17.13 (2026), effective Jan. 1, 2026 (WA L&I''s CPI-indexed annual adjustment).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, 'key', N'https://lni.wa.gov/workers-rights/_docs/2026MinimumWageAnnouncementEnglish.pdf', N'2026 Minimum Wage Announcement poster, Form FY26-120 [09-2025]', N'Washington''s minimum wage will be $17.13 per hour beginning Jan. 1, 2026. Workers who are 14 or 15 years old may be paid 85% of the adult minimum wage, or $14.56 per hour.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Yes — up from $16.66 (2025) to $17.13 (2026), effective Jan. 1, 2026 (WA L&I''s CPI-indexed annual adjustment).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (22, 'key', N'https://lni.wa.gov/workers-rights/wages/minimum-wage/', N'refuter independent check', N'Confirmed. (1) Downloaded lni.wa.gov/workers-rights/wages/minimum-wage/ and read the full HTML text: ''The 2026 minimum wage in the state of Washington is $17.13 per hour.'' 2025 was $16.66, and minors 14-15 get no less than 85%. (2) Downloaded 2026MinimumWageAnnouncementEnglish.pdf (FY26-120 [09-2025]) and read it with PdfPig: $17.13 beginning Jan. 1, 2026; 14-15 year olds 85%, or $14.56. No mid-year change mentioned.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Draft wording is good: ''statewide'' excludes Seattle and other local rates, and ''16 and older'' excludes the 14-15 rate. Small fix to the researcher''s version: L&I does not call the 14-15 rate a ''training rate''. It says 14-15 year olds may be paid 85% of the adult minimum ($14.56). Drop the word ''training'' or use the draft as-is. The 2027 rate is due Sept 30, 2026, but naming 2026 makes that irrelevant.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, 'key', N'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500', N'IR-2025-111, Nov. 13, 2025', N'The Internal Revenue Service announced today that the amount individuals can contribute to their 401(k) plans in 2026 has increased to $24,500, up from $23,500 for 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Up from $23,500 (2025) to $24,500 (2026) — annual IRS inflation COLA under IRC §402(g)(3).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, 'key', N'https://www.irs.gov/pub/irs-drop/n-25-67.pdf', N'Notice 2025-67, 2026 Amounts Relating to Retirement Plans and IRAs', N'elective deferrals described in section 402(g)(3), which includes elective deferrals made to the Thrift Savings Plan, is increased from $23,500 to $24,500.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Up from $23,500 (2025) to $24,500 (2026) — annual IRS inflation COLA under IRC §402(g)(3).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (16, 'key', N'https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500', N'refuter independent check', N'Downloaded and read the full text myself. (1) Notice 2025-67 PDF (irs.gov/pub/irs-drop/n-25-67.pdf), p.1: the 402(g)(1) limit ''is increased from $23,500 to $24,500''. Base catch-up is $8,000, age 60-63 catch-up stays $11,250, SIMPLE is $17,000. (2) IR-2025-111 HTML, Nov. 13, 2025: the 401(k)/403(b)/457/TSP limit ''is increased to $24,500'', and $32,500 with the 50+ catch-up. (3) Searched P.L. 119-21 (OBBBA) on govinfo for supersession: its only 402(g) reference is a cross-reference in the Trump-account provisions. The limit is not amended. Found no later IRS notice or correction.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Clear. Excluding catch-up rules out 32,500 and the age 60-63 figure. The only other number a model could land on is the SIMPLE 401(k) limit of $17,000, and ''a 401(k) plan'' does not reasonably point there. Optional hardening: ''the IRC section 402(g) limit on employee elective deferrals to a 401(k) plan (not a SIMPLE 401(k))''.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-19.pdf', N'Rev. Proc. 2025-19, 2026 HSA inflation-adjusted amounts', N'For calendar year 2026, the annual limitation on deductions under § 223(b)(2)(A) for an individual with self-only coverage under a high deductible health plan is $4,400.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Up from $4,300 (2025) to $4,400 (2026) — annual IRS inflation adjustment under IRC §223(b)(2)(A).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (17, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-19.pdf', N'refuter independent check', N'Read myself. (1) Rev. Proc. 2025-19 PDF full text: ''For calendar year 2026, the annual limitation on deductions under 223(b)(2)(A) for an individual with self-only coverage ... is $4,400''. Family is $8,750. (2) Pub 15-B (For use in 2026) PDF: ''For 2026, you can contribute up to $4,400 for self-only coverage under an HDHP or $8,750 for family coverage''. (3) Pub 969, revision dated Feb 11, 2026 (after OBBBA), tip: ''For 2026, if you have self-only HDHP coverage, you can contribute up to $4,400''. The IRS About Pub 969 page (last reviewed 30-Mar-2026) lists recent developments as ''None at this time''. P.L. 119-21 has no amendment to 223(b)(2).', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Self-only isolates $4,400 from the $8,750 family limit, and 2026 is a calendar year for HSAs, so the year can''t be misread. The age-55 catch-up of $1,000 is statutory, so a model could in theory answer 5,400, but with no age given a careful model answers 4,400. Optional hardening, to match N5: add ''not counting the age-55 catch-up contribution''.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, 'key', N'https://www.govinfo.gov/content/pkg/PLAW-119publ21/html/PLAW-119publ21.htm', N'Public Law 119-21 ("One Big Beautiful Bill Act"), Sec. 70404', N'SEC. 70404. ENHANCEMENT OF THE DEPENDENT CARE ASSISTANCE PROGRAM. (a) In General.--Section 129(a)(2)(A) is amended by striking ``$5,000 ($2,500'''' and inserting ``$7,500 ($3,750''''. (b) Effective Date.--The amendment made by this section shall apply to taxable years beginning after December 31, 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Statutory increase (not an IRS COLA) from $5,000 to $7,500 for joint filers ($2,500 to $3,750 for MFS) — first change since 1986, enacted by OBBBA (Public Law 119-21) §70404, amending IRC §129(a)(2)(A), effective for taxable years beginning after 12/31/2025. Confirmed absent from IRS''s Rev. Proc. 2025-32 list of annually-indexed items, since it is a fixed statutory amount, not inflation-indexed for 2026.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (18, 'key', N'https://www.govinfo.gov/content/pkg/PLAW-119publ21/html/PLAW-119publ21.htm', N'refuter independent check', N'Read myself. (1) P.L. 119-21 HTML on govinfo, SEC. 70404: 129(a)(2)(A) amended by striking ''$5,000 ($2,500'' and inserting ''$7,500 ($3,750'', effective for taxable years beginning after Dec. 31, 2025. The quote matches exactly. (2) Pub 15-B (For use in 2026) PDF, What''s New: ''For the 2026 tax year, the annual dependent care FSA limit was raised from $5,000 to $7,500 ($2,500 to $3,750 for married filing separately)''. p.10 says ''exclude from gross income up to $7,500 ($3,750 if married filing separately)''. (3) Rev. Proc. 2025-32 has no 129 inflation item, which fits a fixed statutory amount. The IRS About Pub 15-B recent-developments list has no correction on dependent care. I found no later law changing 129.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: ''Married couple filing jointly'' correctly excludes the $3,750 married-filing-separately figure, and $7,500 is a per-return household cap, not per spouse. The limit applies per taxable year, so a non-calendar FSA plan year does not change the answer. Models with pre-July-2025 training will say 5000, which is a real miss, not a wording flaw. Optional: ''for the 2026 tax year'', to match Pub 15-B''s phrasing.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'Rev. Proc. 2025-32', N'For taxable years beginning in 2026, the standard deduction amounts under § 63(c)(2) are as follows: ... Unmarried Individuals (other than Surviving Spouses and Heads of Households) (§ 1(j)(2)(C)) $16,100', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Standard deduction (single/MFS) rose from $15,750 (2025) to $16,100 (2026), indexed for inflation under OBBBA-amended §63(c)(7), which made the higher TCJA-era base permanent.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, 'key', N'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill', N'IRS Newsroom: IRS releases tax inflation adjustments for tax year 2026', N'For single taxpayers and married individuals filing separately, the standard deduction rises to $16,100 for tax year 2026', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Standard deduction (single/MFS) rose from $15,750 (2025) to $16,100 (2026), indexed for inflation under OBBBA-amended §63(c)(7), which made the higher TCJA-era base permanent.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (19, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'refuter independent check', N'Downloaded and extracted full text of Rev. Proc. 2025-32 (sec. 2.08 and 4.14), the IR-2025-103 newsroom page, the 2026 Form 1040-ES PDF, Pub 505 (2026) HTML and the 2026 Pub 15-T PDF. All say $16,100 for single filers in 2026. Ran an irs.gov search for any law passed after Oct 2025 that changes the 2026 standard deduction and found none.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key holds. I found no later change. Rev. Proc. 2025-32 says to check for laws passed after Oct 9, 2025, so I checked two later IRS documents: the 2026 Form 1040-ES and Pub 505 (2026). Both still say $16,100. The 2026 Pub 15-T also uses 16,100.00. The only other answers a careful model could give come from situations the prompt doesn''t mention: age 65+ or blind adds $2,050 (total $18,150), a dependent''s deduction is capped, and some models may mix in OBBBA''s separate $6,000 senior deduction. Optional tightening if you want it bulletproof: ''What is the basic standard deduction for a single filer who is under 65, not blind, and cannot be claimed as a dependent, for tax year 2026? Give only the dollar amount, no other text.''', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (20, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'Rev. Proc. 2025-32', N'Over $640,600 $191,171 plus 37% of the excess over $640,600 (Table 3, Unmarried Individuals, taxable years beginning in 2026)', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Unchanged. OBBBA (signed July 2025) made the 37% top rate permanent, canceling the scheduled reversion to 39.6%; only the bracket dollar thresholds moved for inflation.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (20, 'key', N'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill', N'IRS Newsroom: IRS releases tax inflation adjustments for tax year 2026', N'For tax year 2026, the top tax rate remains 37% for individual single taxpayers with incomes greater than $640,600 ($768,700 for married couples filing jointly).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Unchanged. OBBBA (signed July 2025) made the 37% top rate permanent, canceling the scheduled reversion to 39.6%; only the bracket dollar thresholds moved for inflation.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (20, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-32.pdf', N'refuter independent check', N'Read full text of Rev. Proc. 2025-32: sec. 2.01 (OBBBA made the 7 rates permanent) and Tables 1-4. Read IR-2025-103 (''top tax rate remains 37%''). Read the 2026 Form 1040-ES tax rate schedules, which show 37% above $640,600 single and $768,700 MFJ. Recomputed the single and HoH brackets by hand, which is how I caught the misattributed quote.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: 37 holds. The researcher misread one quote, though the key is unaffected. They cited ''$191,171 plus 37% of the excess over $640,600'' as Table 3 (single), but that row comes from Table 2 (Head of Household). It spilled past a page break in the PDF text. I rebuilt the HoH brackets and they reach $191,171; the 1040-ES schedules show the same split. The real single row is ''$192,979.25 plus 37%''. Fix that source quote. Wording is fine. A few models might add the 3.8% NIIT and answer 40.8. Optional tightening: ''What is the top marginal rate in the regular federal individual income tax brackets for tax year 2026, excluding the Net Investment Income Tax and Additional Medicare Tax? Give only the percentage as a number, no other text.''', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-25.pdf', N'Rev. Proc. 2025-25', N'For plan years beginning in calendar year 2026, the Required Contribution Percentage for purposes of § 36B(c)(2)(C)(i)(II) and § 1.36B-2(c)(3)(v)(C) is 9.96%.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'Increased from 9.02% (2025) to 9.96% (2026) -- the highest since ACA indexing began -- driven by a new HHS premium-growth measurement methodology adopted for 2026 (folds in individual-market premium growth, not just employer-sponsored).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (27, 'key', N'https://www.irs.gov/pub/irs-drop/rp-25-25.pdf', N'refuter independent check', N'Downloaded and read full text of Rev. Proc. 2025-25 (sec. 3.02 = 9.96%, effective for plan years beginning in 2026). Found and read Rev. Proc. 2026-26 to check it doesn''t supersede 2026 (it covers 2027 only). Read IRS ACA employer shared responsibility Q&A #39 to confirm that ''affordability'' uses the §36B indexed percentage.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key holds. Rev. Proc. 2026-26 is now out and sets 10.22% for plan years beginning in 2027. It does not modify Rev. Proc. 2025-25; its only effect on other documents is supplementing Rev. Proc. 2014-37. So the prompt''s explicit ''plan years beginning in 2026'' is essential; keep it. IRS employer Q&A #39 (page updated 20-Jul-2026) ties employer affordability to ''9.5 percent (as adjusted)'', which is this same indexed percentage. That confirms ''employer affordability percentage'' points to 9.96 and not a different HHS figure. Minor note: the researcher''s ''highest since indexing began'' is only true through 2026, since 2027 is higher.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, 'key', N'https://www.irs.gov/newsroom/irs-sets-2026-business-standard-mileage-rate-at-725-cents-per-mile-up-25-cents', N'IR-2025-128, Dec. 29, 2025', N'Beginning Jan. 1, 2026, the standard mileage rates for the use of a car, van, pickup or panel truck will be: 72.5 cents per mile driven for business use, up 2.5 cents from 2025.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'IRS set the 2026 business rate at 72.5 cents/mile (up from 70 cents in 2025), effective Jan 1, 2026, via Notice 2026-10 (announced Dec 29, 2025, IR-2025-128). Then, in an unprecedented mid-year move, IRS Announcement 2026-11 (IRB 2026-29) raised it to 76 cents/mile effective July 1, 2026, citing rising fuel prices. As of today (2026-09-17) the rate actually in effect is 76 cents -- the draft''s 72.5 is only correct for Jan-Jun 2026.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, 'key', N'https://www.irs.gov/irb/2026-29_irb', N'Internal Revenue Bulletin 2026-29, Announcement 2026-11', N'The revised standard mileage rates are: (1) Business 76 cents per mile ... apply to deductible transportation expenses paid or incurred for business, medical, or moving expense purposes on or after July 1, 2026', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'IRS set the 2026 business rate at 72.5 cents/mile (up from 70 cents in 2025), effective Jan 1, 2026, via Notice 2026-10 (announced Dec 29, 2025, IR-2025-128). Then, in an unprecedented mid-year move, IRS Announcement 2026-11 (IRB 2026-29) raised it to 76 cents/mile effective July 1, 2026, citing rising fuel prices. As of today (2026-09-17) the rate actually in effect is 76 cents -- the draft''s 72.5 is only correct for Jan-Jun 2026.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (28, 'key', N'https://www.irs.gov/irb/2026-29_irb', N'refuter independent check', N'Read IR-2025-128 (72.5 from Jan 1, 2026) and Notice 2026-10 (full PDF text: 72.5). Read IRB 2026-29, Announcement 2026-11: it changes Notice 2026-10 to 76 cents business for costs on or after July 1, 2026, and keeps Notice 2026-10''s rates for costs before July 1. Read the current IRS standard mileage rates page, downloaded today. It lists 76 for Jul 1-Dec 31 (IR-2026-29) and 72.5 for Jan 1-Jun 30, shows no later change, and shows the earlier mid-year changes in 2022 and 2011.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fix-needed: The draft prompt (''in 2026'') has two correct answers: 72.5 for Jan 1-Jun 30 and 76 for Jul 1-Dec 31 (Announcement 2026-11). As drafted, the key would mislabel models that know about the July change. 72.5 is correct only if the date range is pinned. The researcher''s proposed prompt works but is clunky, and it leans on a notice number that models may not know. Use this instead: ''What is the IRS optional standard mileage rate, in cents per mile, for business use of a car for miles driven from January 1, 2026 through June 30, 2026? Give only the number, no other text.'' Key 72.5. Alternatively, ask about miles driven July 1-December 31, 2026, with key 76; that one tests newer knowledge. Correction to the researcher''s notes: this change was not ''unprecedented''. The IRS rate table shows earlier mid-year changes in 2022 (58.5 to 62.5) and 2011 (51 to 55.5).', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (13, 'key', N'https://www.irs.gov/newsroom/schedule-1-a-additional-deductions-what-to-know-about-the-new-form', N'FS-2026-04, "Schedule 1-A, Additional Deductions: What to know about the new form," March 2026', N'Schedule 1-A is used to claim the following tax deductions: Tip deduction (no tax on tips) ... Overtime deduction (no tax on overtime) ... Car loan interest deduction (no tax on car loan interest) ... Senior deduction (enhanced deduction for seniors)', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged - these are the same 4 OBBBA deductions (tips, overtime, car loan interest, seniors) that Schedule 1-A Parts II-V cover; question asks about tax year 2025 specifically (when the form was introduced) and that fact does not change by asking it in 2026', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (13, 'key', N'https://www.irs.gov/pub/irs-pdf/f1040s1a.pdf', N'Schedule 1-A (Form 1040), Additional Deductions, 2025 (Created 11/4/25)', N'Part II No Tax on Tips ... Part III No Tax on Overtime ... Part IV No Tax on Car Loan Interest ... Part V Enhanced Deduction for Seniors', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged - these are the same 4 OBBBA deductions (tips, overtime, car loan interest, seniors) that Schedule 1-A Parts II-V cover; question asks about tax year 2025 specifically (when the form was introduced) and that fact does not change by asking it in 2026', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (13, 'key', N'https://www.irs.gov/newsroom/schedule-1-a-additional-deductions-what-to-know-about-the-new-form', N'refuter independent check', N'Downloaded https://www.irs.gov/pub/irs-pdf/f1040s1a.pdf (2025, Created 11/4/25) and extracted the full text with PdfPig: Part II No Tax on Tips, Part III No Tax on Overtime, Part IV No Tax on Car Loan Interest, Part V Enhanced Deduction for Seniors, and Part VI adds lines 13, 21, 30 and 37 only. Downloaded the IRS FS-2026-04 page (March 2026) and stripped the HTML: it says the schedule was ''created to calculate and claim four new tax deductions'' and lists tip, overtime, car loan interest and senior deductions. The i1040s1a.pdf URL returned 404, so the separate instructions were not read.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key holds. The form has exactly four deduction parts (II to V); Part I is the MAGI calculation and Part VI is the total, so neither is a deduction a careful model would list. The main risk is grading, not wording: models will use either the slogan names (No Tax on Tips) or the official line names (qualified tips deduction, qualified overtime compensation deduction, qualified passenger vehicle loan interest deduction, enhanced deduction for seniors). The grader must accept both by meaning. The researcher''s suggested prompt is fine, but ''using their common short names'' adds nothing when grading is by meaning, and ''four'' gives away the count. Optional cleaner version: ''Schedule 1-A (Form 1040) was introduced for tax year 2025. List each deduction it is used to claim, one per line. No numbering, no other text.''', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (14, 'key', N'https://uscode.house.gov/view.xhtml?req=granuleid%3AUSC-prelim-title26-section225&num=0&edition=prelim', N'26 U.S.C. Section 225, Qualified overtime compensation (prelim release incorporating OBBBA, P.L. 119-21)', N'The amount allowed as a deduction under this section for any taxable year shall not exceed $12,500 ($25,000 in the case of a joint return).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged - 26 U.S.C. Section 225(b)(1) fixes the cap at $12,500 single / $25,000 joint with no inflation-indexing language anywhere in the statute; IRS FS-2026-13 (updated Aug 6, 2026, the current live FAQ) uses the identical $12,500 figure in its 2026 worked examples', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (14, 'key', N'https://www.irs.gov/pub/taxpros/fs-2026-13.pdf', N'FS-2026-13, "Updates to questions and answers about the new deduction for qualified overtime compensation," August 2026', N'The deduction is up to $12,500 of qualified overtime compensation earned for the year per individual tax return ($25,000 in the case of a joint return)... Employer paid Individual A qualified overtime compensation of $10,000 in 2026... the overall limit on the deduction for qualified overtime compensation is $12,500 ($25,000 in the case of a joint return).', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged - 26 U.S.C. Section 225(b)(1) fixes the cap at $12,500 single / $25,000 joint with no inflation-indexing language anywhere in the statute; IRS FS-2026-13 (updated Aug 6, 2026, the current live FAQ) uses the identical $12,500 figure in its 2026 worked examples', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (14, 'key', N'https://uscode.house.gov/view.xhtml?req=granuleid%3AUSC-prelim-title26-section225&num=0&edition=prelim', N'refuter independent check', N'Downloaded 26 USC 225 from uscode.house.gov (prelim). Subsection (b)(1): ''shall not exceed $12,500 ($25,000 in the case of a joint return)''. It has no inflation-indexing language, and (g) ends the deduction for taxable years after 2028. Downloaded https://www.irs.gov/pub/taxpros/fs-2026-13.pdf (August 2026, supersedes FS-2026-01) and extracted the full text: A2 gives ''up to $12,500 ... ($25,000 in the case of a joint return)'', and the 2026 examples in A10 and A19 repeat the $12,500 overall limit. Cross-checked the 2026 W-2/W-3 instructions (''up to $12,500 ($25,000 if married filing jointly)'') and the 2025 Schedule 1-A line 15 (''$12,500 ($25,000 if married filing jointly)''). The IRS 2026 inflation-adjustment release (IR-2025-103) does not mention overtime, which fits a cap that is not indexed.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key 12500 holds for tax year 2026. ''Single filer'' is unambiguous: every non-joint return gets the same $12,500 cap, and married filing separately cannot claim it at all. The cap comes before the MAGI phaseout, so ''maximum'' can only mean 12,500. Draft wording is acceptable. The suggested prompt (''before any income-based phaseout'', ''no commas, no dollar sign'') is slightly better for exact-match grading. Either way, the grader should normalize ''$12,500'' to 12500.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, 'key', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version', N'Configure language version - C# reference (ms.date 2026-01-16)', N'the default version aligns with the project''s target framework (TFM)... For example, changing the target TFM (for example, from .NET 6 to .NET 9) updates the language version accordingly, from C# 10 to C# 13.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged (set at .NET 10 / C# 14 release, Nov 2025; C# 15 exists only as future/preview, not the net10.0 default)', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, 'key', N'https://learn.microsoft.com/en-us/dotnet/csharp/whats-new/csharp-14', N'What''s new in C# 14 (ms.date 2025-11-18, updated 2026-09-03)', N'C# 14 is the latest C# release. C# 14 is supported on .NET 10.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged (set at .NET 10 / C# 14 release, Nov 2025; C# 15 exists only as future/preview, not the net10.0 default)', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (25, 'key', N'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/language-versioning', N'refuter independent check', N'Downloaded this session with Invoke-WebRequest and stripped to text: (1) learn.microsoft.com language-versioning page, Defaults table .NET 10.x = C# 14, .NET 11.x = C# 15; (2) configure-language-version page, which has no .NET 10 mapping, so the researcher''s quote doesn''t support the key; (3) whats-new/csharp-14 page (''C# 14 is the latest C# release. C# 14 is supported on .NET 10'') and the version history page (C# 14 released November 2025). No revision changes the net10.0 default. C# 15 is tied only to .NET 11.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fix-needed: Key 14 holds. But the researcher''s main cite is weak: the configure-language-version page (downloaded, updated 2026-01-20) only gives a .NET 6 -> 9 example and never says .NET 10 -> C# 14. Their second cite says C# 14 is ''supported on .NET 10'', which is not the same as the default. The real source is the language-versioning page, whose Defaults table maps .NET 10.x to C# 14. Wording hole: that same page says setting LangVersion=default means the compiler''s latest major version, ignoring the TFM. With the .NET 11 SDK (go-live as of Sept 2026) that is C# 15, so a careful model could read ''default'' as the keyword. Fix: ''In 2026, what C# language version does the compiler use by default for a project targeting .NET 10 (TargetFramework net10.0) when LangVersion is not set in the project file? Give only the major version as a whole number, no other text.'' Drop the ''e.g. 12'' example so it can''t anchor an answer. Accept 14 or 14.0 in grading.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (26, 'key', N'https://dotnet.microsoft.com/en-us/platform/support/policy/dotnet-core', N'.NET and .NET Core Official Support Policy', N'.NET 10 | November 11, 2025 | 10.0.12 | September 8, 2026 | LTS | Active | November 14, 2028', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'unchanged since .NET 10''s Nov 11, 2025 release; EOL date fixed by Microsoft''s 3-year LTS policy aligned to the nearest Patch Tuesday', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (26, 'key', N'https://learn.microsoft.com/en-us/lifecycle/products/microsoft-net-and-net-core', N'refuter independent check', N'Downloaded this session: (1) dotnet.microsoft.com .NET support policy page, row ''.NET 10 | November 11, 2025 | 10.0.12 | September 8, 2026 | LTS | Active | November 14, 2028''; (2) the official release metadata JSON (dotnetcli.blob.core.windows.net releases-index.json and 10.0/releases.json), eol-date ''2028-11-14'', latest-release 10.0.12 on 2026-09-08, support-phase active; (3) the learn.microsoft.com Lifecycle product page, End Date 11/15/2028 6:59:59 AM UTC, which is Nov 14, 2028 in Pacific time. None of the three shows an extension or change to the LTS end date.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key 2028-11-14 confirmed three ways. One small risk: the server-rendered HTML of the Microsoft Lifecycle page shows the end date as ''11/15/2028 6:59:59 AM'', a UTC stamp for the end of Nov 14 Pacific, even though the page says dates are in Pacific time. A model that scraped that raw HTML might say 2028-11-15. That is unlikely and not a reasonable reading for a careful model. Optional anchor: ''According to Microsoft''s .NET support policy, on what date does support for .NET 10 (LTS) end? Give only the date as YYYY-MM-DD, no other text.'' Leave out ''As of 2026''. It adds nothing and hints the date might move.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (12, 'key', N'computed locally — no external source', N'Session computation, method 1 (regular pay + OT premium at 1.5x)', N'$reg=40*28.50=1140; $ot=(47-40)*28.50*1.5=299.25; total = 1140 + 299.25 = 1439.25', 'computed', 'research-agent', 'confirmed', N'unchanged — FLSA overtime formula (29 U.S.C. §207(a)(1): time-and-a-half of the regular rate for hours over 40/workweek) is a fixed statutory rule, not indexed or amended annually. Not to be confused with the 2024/2025 DOL rule changes to the EXEMPT salary-basis threshold, which don''t apply here since the employee is stated to be non-exempt and paid hourly.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (12, 'key', N'computed locally — no external source', N'Session computation, method 2 (straight-time on all hours + half-time premium on OT hours)', N'$straightTimeAll=47*28.50=1339.5; $premium=(47-40)*(28.50*0.5)=99.75; total = 1339.5 + 99.75 = 1439.25', 'computed', 'research-agent', 'confirmed', N'unchanged — FLSA overtime formula (29 U.S.C. §207(a)(1): time-and-a-half of the regular rate for hours over 40/workweek) is a fixed statutory rule, not indexed or amended annually. Not to be confused with the 2024/2025 DOL rule changes to the EXEMPT salary-basis threshold, which don''t apply here since the employee is stated to be non-exempt and paid hourly.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (12, 'key', N'https://www.dol.gov/agencies/whd/fact-sheets/23-flsa-overtime-pay', N'Fact Sheet #23: Overtime Pay Requirements of the FLSA', N'employees covered by the Act must receive overtime pay for hours worked in excess of 40 in a workweek at a rate not less than time and one-half their regular rates of pay.', 'webfetch-summary-only', 'research-agent', 'confirmed', N'unchanged — FLSA overtime formula (29 U.S.C. §207(a)(1): time-and-a-half of the regular rate for hours over 40/workweek) is a fixed statutory rule, not indexed or amended annually. Not to be confused with the 2024/2025 DOL rule changes to the EXEMPT salary-basis threshold, which don''t apply here since the employee is stated to be non-exempt and paid hourly.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (12, 'key', N'https://www.dol.gov/agencies/whd/overtime', N'Overtime Pay (WHD program landing page)', N'employees covered by the Act must receive overtime pay for hours worked over 40 in a workweek at a rate not less than time and one-half their regular rates of pay.', 'webfetch-summary-only', 'research-agent', 'confirmed', N'unchanged — FLSA overtime formula (29 U.S.C. §207(a)(1): time-and-a-half of the regular rate for hours over 40/workweek) is a fixed statutory rule, not indexed or amended annually. Not to be confused with the 2024/2025 DOL rule changes to the EXEMPT salary-basis threshold, which don''t apply here since the employee is stated to be non-exempt and paid hourly.', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (12, 'key', N'computed locally — no external source', N'refuter independent check', N'Primary source read raw via PowerShell Invoke-WebRequest: uscode.house.gov 29 U.S.C. 207(a)(1). Quote: no employer shall employ an employee ''for a workweek longer than forty hours unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed.'' dol.gov still returns 403 to direct download, and so did the eCFR API (406). The researcher''s DOL quotes are summary-only, but the statute itself confirms the rule. Recomputed with decimal math: 40*28.50 + 7*28.50*1.5 = 1439.25. File: C:\Users\DAN\AppData\Local\Temp\claude\C--Temp-ForClaude\96612b21-ce62-4cc7-b512-f9fd3ff936a4\scratchpad\qset\skN1_uscode_207.html', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fix-needed: Key 1439.25 holds. Nothing in 2025-2026 changed the 40-hour / 1.5x rule. The OBBBA ''no tax on overtime'' deduction is an income-tax deduction and does not change gross pay. Only a small wording fix is needed. (1) Your wording rules require an explicit year and the draft has none. (2) ''Give only the dollar amount'' invites ''$1,439.25'', which breaks a strict string match. Suggested: "In 2026, a non-exempt employee is paid $28.50 an hour and worked 47 hours in one workweek. Under the federal FLSA overtime rule, what is their gross pay for that week? Give only the number with two decimal places, no dollar sign or commas, no other text."', 'wf_f18ab8e4-7cc');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, 'key', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-78a', N'MCL 211.78a (General Property Tax Act, Act 206 of 1893), subsection (3)', N'A county property tax administration fee of 4% and, except as provided in section 78g(3)(c), interest computed at a noncompounded rate of 1% per month or fraction of a month on the taxes that were originally returned as delinquent, computed from the date that the taxes originally became delinquent, shall be added to property returned as delinquent under this section. A county property tax administration fee provided for under this subsection shall not be less than $1.00.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'No change. Current text is complete through PA 91 of 2026 (checked 2026-09-17); MCL 211.78a was last amended by 2014 PA 499, eff. Jan 14, 2015. The 4% figure is unchanged since then.', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, 'key', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44', N'MCL 211.44 (General Property Tax Act), subsections (3) and (5) — the DIFFERENT local-unit fee, for contrast', N'the local property tax collecting unit shall add a property tax administration fee of not more than 1% of the total tax bill per parcel ... A 4% county property tax administration fee ... and interest on the tax at the rate of 1% per month shall be added to taxes collected by the township or city treasurer after the last day taxes are payable before being returned as delinquent', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'No change. Current text is complete through PA 91 of 2026 (checked 2026-09-17); MCL 211.78a was last amended by 2014 PA 499, eff. Jan 14, 2015. The 4% figure is unchanged since then.', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (23, 'key', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-44', N'refuter independent check', N'Check 1, statute text (downloaded via Invoke-WebRequest, full page read, compiled through PA 91 of 2026): MCL 211.78a(3) says ''A county property tax administration fee of 4%'' and sets a $1.00 minimum. Last amended by 2014 PA 499. PASS. Check 2, Treasury guidance (michigan.gov/taxes/property/forfeiture-foreclosure/county/foreclosure-process-timelines, full text read): ''March 1 211.78a(3) 4% administration fee and interest computed at a non-compounded rate of 1% per month ... added to delinquent parcel.'' PASS. Check 3, cross-statute and currency: MCL 211.44(3) says a 4% county fee is added to taxes the local treasurer collects after the delinquent return date; MCL 211.60a(1)-(2) and the historical 211.89 also say 4%. The 2026 Public Act Table PDF (legislature.mi.gov, extracted with PdfPig) ends at PA 91, so the compiled MCL is current and no uncompiled 2026 act amends 78a. PASS. Break attempts that failed: the local 1% fee (211.44), the 3% late penalty, the 1%/month interest, and the $1 minimum are all different items. Not verified: the pre-2015 amendment history.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key holds. Owner wording is ambiguous, not wrong: the local unit''s up-to-1% admin fee (MCL 211.44(3)) also travels into the county delinquent roll per 211.44(6), so a careful model could answer ''1% local + 4% county'', or ''4%, minimum $1''. The researcher''s suggested prompt fixes this by naming the county fee and the return-as-delinquent trigger. Minor polish only: end with the standard format sentence and accept ''4'' or ''4%''. Suggested: ''Under Michigan''s General Property Tax Act (MCL 211.78a(3)), what percentage county property tax administration fee is added when unpaid property taxes are returned as delinquent to the county treasurer? Give only the percentage, no other text.''', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (24, 'key', N'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-211-78g', N'MCL 211.78g (General Property Tax Act, Act 206 of 1893), subsection (1)', N'If property is forfeited to a county treasurer under this subsection, the county treasurer shall add a $175.00 fee to each property for which those delinquent taxes, interest, penalties, and fees remain unpaid.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'No change to the $175.00 amount. Current text is complete through PA 91 of 2026 (checked 2026-09-17). MCL 211.78g''s most recent amendment is 2026 PA 79 (imd. eff. July 27, 2026), but that amendment added a new payment-reduction-program (subsections 8-10) — it did not alter the $175.00 forfeiture fee in subsection (1), which has read $175.00 since at least the 2020 amendments (PA 33 and PA 256 of 2020, the post-Rafaeli changes).', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (24, 'key', N'https://www.michigan.gov/taxes/property/forfeiture-foreclosure/county/foreclosure-process-timelines', N'refuter independent check', N'Check 1, statute text (MCL 211.78g, downloaded and fully read, compiled through PA 91 of 2026): ''(1) ... If property is forfeited to a county treasurer under this subsection, the county treasurer shall add a $175.00 fee to each property for which those delinquent taxes, interest, penalties, and fees remain unpaid.'' History shows the latest amendment is 2026 PA 79 (eff. July 27, 2026), and the current post-PA 79 text still says $175.00. PASS. Check 2, Treasury guidance (michigan.gov foreclosure-process-timelines page, full text read): under Tax Year 2, ''March 1 211.78g(1) County treasurer adds $175 title fee to the parcel.'' The amount and per-parcel basis match, but Treasury''s name for it is ''title fee''. PASS on the key, noted on wording. Check 3, currency and neighboring fees: the 2026 Public Act Table PDF (PdfPig extraction) ends at PA 91. PA 79''s subject line reads ''sunsets on certain delinquent tax payment reduction and foreclosure avoidance programs; eliminate'', so it did not change the fee amount. MCL 211.78d ($15 on October 1) is a separate pre-forfeiture fee, not $175. PASS. Not verified: the researcher''s claim that the amount ''has read $175.00 since at least 2020''. The current text makes that irrelevant to the key.', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fair: Key holds. Naming nuance: the statute never calls it a ''forfeiture fee'', and Treasury''s timeline calls the same $175 a ''title fee''. The owner''s term is common county usage, but describing the fee by its trigger (as the researcher''s prompt does) is the right fix. Nearby amounts a loose prompt could pull in: the $15 fee added October 1 of year 1 (MCL 211.78d), the extra 1/2%/month redemption interest (78g(3)(b)), and recording/service fees at redemption (78g(3)(d)). The researcher''s prompt excludes all of them. Optional polish: say ''each property (parcel)'' to match the statute''s ''each property'', and use the standard ending: ''...Give only the dollar amount, no other text.''', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (29, 'key', N'https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type?view=sql-server-ver17', N'Vector Data Type - SQL Server (Microsoft Learn)', N'A vector must have at least one dimension. The maximum number of dimensions supported is 1998.', 'full-page-or-pdf-text', 'research-agent', 'confirmed', N'No change found — current live docs (ms.date 2026-02-18) confirm 1998; matches the owner''s local engine test (VECTOR(1998) succeeded, VECTOR(1999) failed) on SQL Server 2025 RTM 17.0.1000.7.', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes, WorkflowRunId) VALUES (29, 'key', N'https://learn.microsoft.com/en-us/sql/t-sql/data-types/vector-data-type-half-precision-float?view=sql-server-ver17', N'refuter independent check', N'Downloaded and read both pages with Invoke-WebRequest (full HTML stripped to text, no summary). (1) learn.microsoft.com vector-data-type?view=sql-server-ver17, last updated 2026-02-18: 1998 max, float32 is the default, float16 is in preview. (2) learn.microsoft.com vector-data-type-half-precision-float?view=sql-server-ver17, linked from page 1 and last updated 2025-12-08: float16 raises the limit to 3,996, so the prompt has to pin the base type. (3) The owner''s local test on SQL Server 2025 RTM 17.0.1000.7 (from the draft hint, not rerun by me): VECTOR(1998) worked, VECTOR(1999) failed, and float16 was rejected without preview features. That fits a 1998 key for float32. Files: C:\Users\DAN\AppData\Local\Temp\claude\C--Temp-ForClaude\96612b21-ce62-4cc7-b512-f9fd3ff936a4\scratchpad\qset2\s1_vector.txt and s1_half.txt', 'full-page-or-pdf-text', 'refute-agent', 'confirmed', N'wording fix-needed: Key 1998 holds for the default float32 base type (main vector page, updated 2026-02-18, plus the owner''s RTM engine test). The researcher was wrong to say no base-type pinning was needed. The linked half-precision page (updated 2025-12-08) says float16 supports up to 3,996 dimensions. float16 is in preview behind PREVIEW_FEATURES, but a careful model could still answer 3996, or give both numbers. Fix: "In SQL Server 2025, what is the maximum number of dimensions allowed for a column of the native VECTOR data type using its default base type (float32, with preview features off)? Give only the number, no other text." Doc quotes are cleaned up: the page''s multiplication sign came through mis-encoded and is written as x.', 'wf_6281f330-fa0');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes) VALUES (28, 'key', N'https://www.irs.gov/irb/2026-29_irb', N'IRS Announcement 2026-11, Internal Revenue Bulletin 2026-29', N'The revised standard mileage rates are: (1) Business 76 cents per mile', 'full-page-or-pdf-text', 'claude-direct', 'confirmed', N'Fetched and grepped 2026-09-17.');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes) VALUES (29, 'key', N'localhost SQL Server 2025 RTM 17.0.1000.7', N'engine test', N'VECTOR(1998): created OK; VECTOR(1999): The size (1999) given to the column ''v'' exceeds the maximum allowed (1998).', 'computed', 'engine-test', 'confirmed', N'Run 2026-09-17 in tempdb, compatibility 170.');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes) VALUES (30, 'key', N'localhost SQL Server 2025 RTM 17.0.1000.7', N'engine test', N'rows 1, 2, NULL: NOT IN (1, NULL) returns 0 rows; NOT IN (1) returns 1 row; ANSI_NULLS = 1', 'computed', 'engine-test', 'confirmed', N'Run 2026-09-17 in tempdb.');
INSERT INTO quorum.KeyEvidence (QuestionId, Role, Url, Document, Quote, ReadHow, CheckedBy, Verdict, Notes) VALUES (12, 'key', N'29 U.S.C. 207(a)(1)', N'computation', N'40 x 28.50 = 1140.00; 7 x 42.75 = 299.25; total 1439.25', 'computed', 'claude-direct', 'confirmed', NULL);
